import datetime

# 获取当前日期
class Mytime:

    def my_date(self):
        today_time = datetime.date.today()
        return today_time.strftime(&quot;%Y-%m-%d&quot;)

    def my_time(self):
        current_time = datetime.datetime.now().time()
        return current_time.strftime(&quot;%H:%M:%S&quot;)

# 创建实例
time_print = Mytime()

# 打印当前时间
print(time_print.my_date())
print(time_print.my_time())

